import{_ as t,o as r,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Summit  - RADOS CDS","description":"","frontmatter":{"title":"Ceph Developer Summit  - RADOS CDS","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-11T00:00:00.000Z","tags":["Ceph","分布式存储","BlueStore","Fast EC","Scrub"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_RADOS_CDS.md","filePath":"posts/2025/Ceph_Developer_Summit_-_RADOS_CDS.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Ceph_Developer_Summit_-_RADOS_CDS.md"};function i(s,l,n,h,u,g){return r(),e("div",null,[...l[0]||(l[0]=[a('<p>Ceph 开发者峰会（Ceph Developer Summit - RADOS CDS）会议纪要如下：</p><h2 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h2><ul><li><strong>会议主题</strong>: Ceph 分布式存储 CDS (Ceph Development Summit) 会议</li><li><strong>主要讨论领域</strong>: Ceph 存储系统的多个核心组件与功能改进</li><li><strong>关键词保留策略</strong>: 保留关键技术术语的英文原文</li></ul><h2 id="主要议题讨论" tabindex="-1">主要议题讨论 <a class="header-anchor" href="#主要议题讨论" aria-label="Permalink to &quot;主要议题讨论&quot;">​</a></h2><h3 id="_1-fast-ec-改进" tabindex="-1">1. Fast EC 改进 <a class="header-anchor" href="#_1-fast-ec-改进" aria-label="Permalink to &quot;1. Fast EC 改进&quot;">​</a></h3><ul><li><strong>零检测功能</strong>: 预计将合并到 Umbrella 版本，提高性能</li><li><strong>直接读取优化</strong>: 绕过主 OSD 的性能优化路径</li><li><strong>EC 配置文件/池迁移</strong>: 计划实现无中断的迁移过程，简化配置</li><li><strong>池类统一</strong>: 支持从副本池到 EC 池的无缝迁移</li></ul><h3 id="_2-bluestore-改进" tabindex="-1">2. BlueStore 改进 <a class="header-anchor" href="#_2-bluestore-改进" aria-label="Permalink to &quot;2. BlueStore 改进&quot;">​</a></h3><ul><li><strong>RocksDB 缓存优化</strong>: 解决大元素导致的分片不平衡问题</li><li><strong>快速节点恢复</strong>: 缩短大型 OSD 崩溃后的恢复时间</li><li><strong>分配映射持久性</strong>: 提高 BlueFS 中存储分配信息的效率</li><li><strong>元数据重组</strong>: 重组对象元数据和数据，支持插件化操作</li><li><strong>内存元数据优化</strong>: 使用 PMR 分配器改进内存使用和缓存行为</li><li><strong>CPU 跟踪工具</strong>: 精确测量代码优化效果</li></ul><h3 id="_3-scrub-改进" tabindex="-1">3. Scrub 改进 <a class="header-anchor" href="#_3-scrub-改进" aria-label="Permalink to &quot;3. Scrub 改进&quot;">​</a></h3><ul><li><strong>Crimson 功能补齐</strong>: 添加缺失的 scrub 调度功能</li><li><strong>后端重构</strong>: 改进权威对象版本选择算法，优化性能</li></ul><h3 id="_4-qos-改进" tabindex="-1">4. QoS 改进 <a class="header-anchor" href="#_4-qos-改进" aria-label="Permalink to &quot;4. QoS 改进&quot;">​</a></h3><ul><li><strong>基准测试流程改进</strong>: 提高基准测试结果的可靠性</li><li><strong>子操作处理优化</strong>: 解决客户端操作延迟问题</li><li><strong>mclock 配置调优</strong>: 优化现有配置文件的吞吐量和延迟</li></ul><h3 id="_5-stretch-模式改进" tabindex="-1">5. Stretch 模式改进 <a class="header-anchor" href="#_5-stretch-模式改进" aria-label="Permalink to &quot;5. Stretch 模式改进&quot;">​</a></h3><ul><li><strong>网络分区检测与 OSD 隔离</strong>: 实现基于位置的 OSD 隔离</li><li><strong>CRUSH 权重限制放宽</strong>: 支持不同容量节点的 stretch 集群</li><li><strong>副本数灵活性讨论</strong>: 考虑支持副本 2/3 以节省成本</li></ul><h3 id="_6-应用平衡器-app-balancer" tabindex="-1">6. 应用平衡器(App Balancer) <a class="header-anchor" href="#_6-应用平衡器-app-balancer" aria-label="Permalink to &quot;6. 应用平衡器(App Balancer)&quot;">​</a></h3><ul><li><strong>脚本集成</strong>: 将社区广泛使用的 <code>pg-upmap-remapper</code> 和 <code>pg-remapper</code> 脚本纳入官方仓库</li><li><strong>行为改进</strong>: 处理 PG 非 active+clean 状态，避免集群卡住</li><li><strong>多线程优化</strong>: 提高 PG 操作性能</li><li><strong>OSD 权重支持</strong>: 扩展离线重平衡器的容量感知功能</li></ul><h3 id="_7-其他核心改进" tabindex="-1">7. 其他核心改进 <a class="header-anchor" href="#_7-其他核心改进" aria-label="Permalink to &quot;7. 其他核心改进&quot;">​</a></h3><ul><li><strong>Monitor 辅助连接</strong>: 解决单 monitor 故障导致的服务中断</li><li><strong>BufferList 优化</strong>: 支持零值高效存储，API 重构</li><li><strong>RGW 池索引优化</strong>: 考虑冷存储场景下的简化索引方案</li><li><strong>配置模板</strong>: 支持配置参数的模板化管理</li><li><strong>秘密存储分离</strong>: 将敏感数据从 monitor 配置库移出</li></ul><h3 id="_8-测试能力改进" tabindex="-1">8. 测试能力改进 <a class="header-anchor" href="#_8-测试能力改进" aria-label="Permalink to &quot;8. 测试能力改进&quot;">​</a></h3><ul><li><strong>编解码器测试</strong>: 扩展对象语料库测试，支持双向兼容性验证</li><li><strong>性能测试优化</strong>: 提高文件夹测试效率</li><li><strong>JSON 支持</strong>: 为 Ceph 添加美观的 JSON 格式化输出</li></ul><h2 id="性能优化展示" tabindex="-1">性能优化展示 <a class="header-anchor" href="#性能优化展示" aria-label="Permalink to &quot;性能优化展示&quot;">​</a></h2><ul><li><strong>EC 直接读取性能</strong>: 小读取性能达到副本池水平，大读取延迟降低 66%</li><li><strong>副本池大 IO 优化</strong>: 1MB 顺序读取吞吐量提升显著，延迟从 3ms 降至 1-1.5ms</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>完成Fast EC的零检测和直接读取功能</li><li>合并RocksDB缓存优化</li><li>补齐Scrub的后端重构</li><li>完成 QoS 的基准测试改进</li><li>实现Stretch模式的 OSD 隔离</li><li>合并Monitor的辅助连接支持</li><li>扩展编解码器测试覆盖</li></ul><h2 id="待讨论事项" tabindex="-1">待讨论事项 <a class="header-anchor" href="#待讨论事项" aria-label="Permalink to &quot;待讨论事项&quot;">​</a></h2><ul><li>RocksDB 分片数量的最优配置</li><li>EC 池迁移的用户体验设计</li><li>Stretch 模式支持可变副本数的可行性</li><li>磁盘故障预测功能的必要性评估</li></ul><p>会议记录将上传至 YouTube，相关链接将通过邮件列表和 Slack 共享。</p>',27)])])}const p=t(o,[["render",i]]);export{d as __pageData,p as default};
